import { useEffect, useState } from "react";
import { Capacitor } from "@capacitor/core";
import { Download, RefreshCw } from "lucide-react";
import { Button } from "@/components/ui/button";
import { recordDiagnostic } from "./diagnostics";
import { usePathname } from "./router";

type InstallEvent = Event & { prompt(): Promise<void>; userChoice: Promise<{ outcome: string }> };
let registration: ServiceWorkerRegistration | undefined;
let installPrompt: InstallEvent | undefined;
let updateReady = false;
let offlineReady = false;
const notify = () => window.dispatchEvent(new Event("odessa:pwa"));

export function installPwa(): void {
  if (Capacitor.isNativePlatform() || import.meta.env.MODE !== "pwa") return;
  window.addEventListener("beforeinstallprompt", (event) => { event.preventDefault(); installPrompt = event as InstallEvent; notify(); });
  window.addEventListener("appinstalled", () => { installPrompt = undefined; notify(); });
  if (!("serviceWorker" in navigator)) return;
  let applyingUpdate = false;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (applyingUpdate) window.location.reload();
  });
  window.addEventListener("odessa:apply-update", () => {
    if (!registration?.waiting) return;
    applyingUpdate = true;
    registration.waiting.postMessage({ type: "ACTIVATE_UPDATE" });
  });
  void navigator.serviceWorker.register(`${import.meta.env.BASE_URL}sw.js`, { scope: import.meta.env.BASE_URL, updateViaCache: "none" }).then((value) => {
    registration = value;
    const check = () => { updateReady = Boolean(value.waiting); notify(); };
    check();
    value.addEventListener("updatefound", () => {
      value.installing?.addEventListener("statechange", check);
    });
    void navigator.serviceWorker.ready.then(() => { offlineReady = true; notify(); });
    let lastCheck = Date.now();
    window.addEventListener("odessa:app-resume", () => {
      if (Date.now() - lastCheck < 60 * 60 * 1000) return;
      lastCheck = Date.now();
      void value.update().catch(() => {});
    });
  }).catch((error: unknown) => recordDiagnostic("pwa.install-failed", String(error)));
}

function usePwaState() {
  const [, refresh] = useState(0);
  useEffect(() => {
    const update = () => refresh((n) => n + 1);
    window.addEventListener("odessa:pwa", update);
    const query = matchMedia("(display-mode: standalone)");
    query.addEventListener("change", update);
    return () => { window.removeEventListener("odessa:pwa", update); query.removeEventListener("change", update); };
  }, []);
  const standalone = matchMedia("(display-mode: standalone)").matches || Boolean((navigator as Navigator & { standalone?: boolean }).standalone);
  return { standalone, updateReady, offlineReady, installPrompt };
}

export function PwaInstallCard() {
  const state = usePwaState();
  const [expanded, setExpanded] = useState(false);
  if (Capacitor.isNativePlatform() || import.meta.env.MODE !== "pwa") return null;
  const apple = /iPad|iPhone|iPod/.test(navigator.userAgent) || (navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1);
  return <section className="pwa-install">
    {state.standalone ? <p>Приложение установлено</p> : <>
      <Button variant="secondary" onClick={() => {
        if (!state.installPrompt) { setExpanded((v) => !v); return; }
        void state.installPrompt.prompt().then(() => state.installPrompt?.userChoice).then(() => { installPrompt = undefined; notify(); }).catch(() => setExpanded(true));
      }}><Download size={16} /> Установить приложение</Button>
      {expanded && <p>{apple
        ? "Откройте игру в Safari. Нажмите «Поделиться» → «На экран Домой» → «Добавить». Если есть переключатель «Открывать как веб-приложение», включите его."
        : "В меню браузера выберите «Установить приложение» или «Добавить на главный экран». На компьютере пункт установки может быть в адресной строке. Можно также играть прямо в браузере."}</p>}
    </>}
    <p className="text-xs text-muted-foreground" role="status">{state.offlineReady ? "Игра с ботами доступна без интернета" : "Для первого запуска нужен интернет"}</p>
  </section>;
}

export function PwaUpdateNotice() {
  const state = usePwaState();
  const path = usePathname();
  // Never reload a hand or interrupt voice. Update only after returning to the menu.
  if (!state.updateReady || (path !== "/" && path !== "/settings")) return null;
  return <aside className="pwa-update" role="status"><span>Доступна новая версия</span><Button variant="secondary" onClick={() => window.dispatchEvent(new Event("odessa:apply-update"))}><RefreshCw size={16} /> Обновить</Button></aside>;
}
