import { useSyncExternalStore } from "react";

const listeners = new Set<() => void>();
const emit = () => { for (const listener of listeners) listener(); };

export function currentPath(): string {
  const path = window.location.hash.slice(1) || "/";
  return path === "/" || path === "/bots" || path === "/settings" || /^\/lobby\/[A-Z]{4}$/i.test(path) ? path : "/";
}

const router = {
  push(path: string) { window.location.hash = path; window.scrollTo(0, 0); },
  replace(path: string) { history.replaceState(null, "", `#${path}`); emit(); window.scrollTo(0, 0); },
  back() { history.back(); },
};

export function useRouter() { return router; }

export function usePathname() {
  return useSyncExternalStore((listener) => {
    listeners.add(listener);
    window.addEventListener("hashchange", listener);
    return () => { listeners.delete(listener); window.removeEventListener("hashchange", listener); };
  }, currentPath, () => "/");
}
