import { Capacitor, registerPlugin } from "@capacitor/core";
import { App } from "@capacitor/app";
import { Browser } from "@capacitor/browser";
import { Clipboard } from "@capacitor/clipboard";
import { Share } from "@capacitor/share";
import { configureClientRuntime, normalizeServerOrigin } from "@/lib/net/client-runtime";
import { nativeRequest } from "./transport";
import { shareFile } from "./share-file";
import { recordDiagnostic } from "./diagnostics";

export const DEFAULT_SERVER = "https://odesskiypoker.com";
const SERVER_KEY = "odessa-poker:android:server";
const ProtocolExport = registerPlugin<{ save(options: { text: string }): Promise<{ uri: string }> }>("ProtocolExport");

export function serverOrigin(): string {
  if (!Capacitor.isNativePlatform()) return location.protocol === "https:" ? location.origin : DEFAULT_SERVER;
  try { return normalizeServerOrigin(localStorage.getItem(SERVER_KEY) ?? DEFAULT_SERVER); }
  catch { return DEFAULT_SERVER; }
}

export function setServerOrigin(value: string): void {
  localStorage.setItem(SERVER_KEY, normalizeServerOrigin(value));
  initializePlatform();
}

let viewportInstalled = false;
export function initializePlatform(): void {
  if (!viewportInstalled) {
    viewportInstalled = true;
    const viewport = () => {
      const visual = window.visualViewport;
      const useVisual = visual && visual.scale === 1;
      document.documentElement.style.setProperty("--app-height", `${useVisual ? visual.height : window.innerHeight}px`);
      document.documentElement.style.setProperty("--app-offset-top", `${useVisual ? visual.offsetTop : 0}px`);
    };
    viewport();
    window.addEventListener("resize", viewport);
    window.addEventListener("orientationchange", viewport);
    window.visualViewport?.addEventListener("resize", viewport);
    window.visualViewport?.addEventListener("scroll", viewport);
  }
  const native = Capacitor.isNativePlatform();
  configureClientRuntime({
    apiOrigin: serverOrigin(),
    preferPolling: true,
    persistentSessions: true,
    request: native ? nativeRequest : async (url, init) => {
      const { pathname, search } = new URL(url);
      try {
        const response = await fetch(`${pathname}${search}`, init);
        if (response.status >= 400) recordDiagnostic("http.failure", `${init.method ?? "GET"} ${pathname} status=${response.status}`);
        return response;
      } catch (error) {
        if (!(error instanceof DOMException && error.name === "AbortError")) recordDiagnostic("http.network-error", pathname);
        throw error;
      }
    },
    ...(native ? {
      copyText: async (text: string) => { await Clipboard.write({ string: text }); },
      saveTextFile: async (_name: string, text: string) => {
        const saved = await ProtocolExport.save({ text });
        await Share.share({ title: "Протокол партии", files: [saved.uri], dialogTitle: "Сохранить или отправить протокол" });
      },
    } : {
      lobbyUrl: (code: string) => `${location.origin}${import.meta.env.BASE_URL}index.html#/lobby/${encodeURIComponent(code)}`,
      saveTextFile: (name: string, text: string) => shareFile(name, text, "text/html;charset=utf-8"),
    }),
  });
}

export async function openJournal(): Promise<void> {
  const url = `${serverOrigin()}/turnir`;
  if (Capacitor.isNativePlatform()) await Browser.open({ url });
  else window.open(url, "_blank", "noopener,noreferrer");
}

export function routeFromDeepLink(raw: string): string | null {
  try {
    const url = new URL(raw);
    const path = url.protocol === "odesskiypoker:" && url.host === "lobby"
      ? `/lobby${url.pathname}` : url.origin === serverOrigin() ? url.pathname : "";
    return /^\/lobby\/[A-Z]{4}$/i.test(path) ? path.toUpperCase().replace("/LOBBY/", "/lobby/") : null;
  } catch { return null; }
}

export async function installLifecycle(): Promise<void> {
  if (!Capacitor.isNativePlatform()) {
    let active = !document.hidden;
    const update = (next: boolean) => {
      if (next === active) return;
      active = next;
      window.dispatchEvent(new Event(active ? "odessa:app-resume" : "odessa:app-background"));
    };
    document.addEventListener("visibilitychange", () => update(!document.hidden));
    window.addEventListener("pagehide", () => update(false));
    window.addEventListener("pageshow", () => update(!document.hidden));
    return;
  }
  await App.addListener("appStateChange", ({ isActive }) => {
    window.dispatchEvent(new Event(isActive ? "odessa:app-resume" : "odessa:app-background"));
  });
  await Browser.addListener("browserFinished", () => window.dispatchEvent(new Event("odessa:app-resume")));
  await App.addListener("appUrlOpen", ({ url }) => {
    const route = routeFromDeepLink(url);
    if (route) window.location.hash = route;
  });
  const launch = await App.getLaunchUrl();
  const route = launch && routeFromDeepLink(launch.url);
  if (route) window.location.hash = route;
}
