import { Component, useEffect, useState, useSyncExternalStore, type ErrorInfo, type ReactNode } from "react";
import { Capacitor } from "@capacitor/core";
import { App } from "@capacitor/app";
import { Dialog } from "@capacitor/dialog";
import { ArrowLeft, RefreshCw, Settings, WifiOff } from "lucide-react";
import { MainMenu } from "@/components/menu/main-menu";
import { LobbyScreen } from "@/components/menu/lobby-screen";
import { GameTable } from "@/components/game/game-table";
import { Backdrop, Title } from "@/components/menu/backdrop";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { lastLobby, subscribeSession } from "@/lib/net/session";
import { apiFetch, normalizeServerOrigin } from "@/lib/net/client-runtime";
import { usePathname, useRouter, currentPath } from "./router";
import { openJournal, serverOrigin, setServerOrigin, DEFAULT_SERVER } from "./platform";
import { dismissReport, hasPendingReport, recordError, shareDiagnostics } from "./diagnostics";

import { PwaInstallCard, PwaUpdateNotice } from "./pwa";
import { APP_VERSION } from "./app-info";

export function MobileApp() {
  const path = usePathname();
  const [online, setOnline] = useState(navigator.onLine);
  const [notice, setNotice] = useState("");
  useEffect(() => {
    const updateNetwork = () => setOnline(navigator.onLine);
    const showNotice = (event: Event) => setNotice(String((event as CustomEvent).detail));
    const journalLink = (event: MouseEvent) => {
      const link = (event.target as Element).closest?.("a");
      if (link?.getAttribute("href") !== "/turnir") return;
      event.preventDefault();
      void openJournal().catch(() => setNotice("Не удалось открыть журнал турнира"));
    };
    window.addEventListener("online", updateNetwork);
    window.addEventListener("offline", updateNetwork);
    window.addEventListener("odessa:notice", showNotice);
    document.addEventListener("click", journalLink);
    let removed = false;
    const nativeBack = Capacitor.isNativePlatform() ? App.addListener("backButton", () => {
      const close = document.querySelector<HTMLButtonElement>('[data-slot="dialog-content"] [data-slot="dialog-close"]');
      if (close) { close.click(); return; }
      const current = currentPath();
      if (current === "/") { void App.minimizeApp(); return; }
      if (current === "/settings") { window.location.hash = "/"; return; }
      void Dialog.confirm({
        title: "Вернуться в меню?",
        message: current === "/bots" ? "Текущая партия с ботами будет завершена." : "Место за столом сохранится. Вы сможете вернуться из главного меню.",
        okButtonTitle: "В меню", cancelButtonTitle: "Продолжить игру",
      }).then(({ value }) => { if (value) window.location.hash = "/"; });
    }) : null;
    void nativeBack?.then((handle) => { if (removed) void handle.remove(); });
    return () => {
      removed = true;
      void nativeBack?.then((handle) => handle.remove());
      window.removeEventListener("online", updateNetwork);
      window.removeEventListener("offline", updateNetwork);
      window.removeEventListener("odessa:notice", showNotice);
      document.removeEventListener("click", journalLink);
    };
  }, []);
  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => setNotice(""), 7000);
    return () => clearTimeout(timer);
  }, [notice]);
  return <ErrorBoundary>
    <CrashNotice />
    <PwaUpdateNotice />
    {!online && <div className="connection-banner" role="status"><WifiOff size={16} /> Нет интернета. Игра с ботами доступна.</div>}
    {path === "/bots" ? <GameTable /> : path.startsWith("/lobby/") ? <LobbyScreen key={path} code={path.split("/")[2]} /> : path === "/settings" ? <SettingsScreen /> : <Home />}
    {notice && <div className="mobile-notice" role="status" onClick={() => setNotice("")}>{notice}</div>}
  </ErrorBoundary>;
}

function SendLogsButton() {
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  return <div className="flex flex-col gap-2">
    <Button variant="secondary" disabled={busy} onClick={() => {
      setBusy(true); setError("");
      void shareDiagnostics().catch(() => setError("Не удалось открыть отправку. Попробуйте ещё раз.")).finally(() => setBusy(false));
    }}>{busy ? "Готовим отчёт…" : "Отправить логи разработчику"}</Button>
    {error && <p role="alert" className="text-sm text-ember">{error}</p>}
  </div>;
}

function CrashNotice() {
  const [pending, setPending] = useState(false);
  useEffect(() => {
    const refresh = () => { void hasPendingReport().then(setPending).catch(() => {}); };
    refresh();
    window.addEventListener("odessa:diagnostic-error", refresh);
    window.addEventListener("odessa:app-resume", refresh);
    return () => {
      window.removeEventListener("odessa:diagnostic-error", refresh);
      window.removeEventListener("odessa:app-resume", refresh);
    };
  }, []);
  return pending && <aside className="crash-notice" role="status">
    <p>Сохранён отчёт о сбое. Его можно отправить разработчику.</p>
    <div className="flex flex-wrap gap-2"><SendLogsButton /><Button variant="ghost" onClick={() => {
      void dismissReport().then(() => setPending(false));
    }}>Скрыть</Button></div>
  </aside>;
}

function Home() {
  const router = useRouter();
  const code = useSyncExternalStore(subscribeSession, lastLobby, () => null);
  return <MainMenu extra={<div className="mobile-home-extra">
    {code && <Button variant="secondary" onClick={() => router.push(`/lobby/${code}`)}><RefreshCw /> Вернуться за стол {code}</Button>}
    <Button variant="ghost" onClick={() => router.push("/settings")}><Settings /> Настройки</Button>
    <PwaInstallCard />
  </div>} />;
}

function SettingsScreen() {
  const router = useRouter();
  const [address, setAddress] = useState(serverOrigin);
  const [message, setMessage] = useState("");
  const [busy, setBusy] = useState(false);
  const save = () => {
    try { setServerOrigin(address); router.replace("/"); }
    catch (error) { setMessage(error instanceof Error ? error.message : "Проверьте адрес"); }
  };
  const check = async () => {
    setBusy(true);
    try {
      if (normalizeServerOrigin(address) !== serverOrigin()) throw new Error("Сначала сохраните новый адрес");
      const response = await apiFetch("/api/turnir/players");
      if (!response.ok || !Array.isArray(await response.json())) throw new Error("Сервер игры не ответил. Проверьте адрес и интернет.");
      setMessage("Связь с сервером есть");
    } catch (error) { setMessage(error instanceof Error ? error.message : "Нет связи с сервером"); }
    finally { setBusy(false); }
  };
  return <Backdrop>
    <Title subtitle="Настройки приложения" />
    <section className="flex flex-col gap-4 rounded-xl border border-white/10 bg-black/50 p-5">
      <Label htmlFor="server">Сайт игры</Label>
      <Input readOnly={!Capacitor.isNativePlatform()} id="server" type="url" autoCapitalize="none" autoCorrect="off" spellCheck={false} value={address} onChange={(event) => { setAddress(event.target.value); setMessage(""); }} />
      <p className="text-sm text-muted-foreground">Для общей партии у всех игроков должен быть один сайт.</p>
      {Capacitor.isNativePlatform() && <Button onClick={save}>Сохранить</Button>}
      <Button variant="secondary" onClick={() => void check()} disabled={busy}>{busy ? "Проверяем…" : "Проверить связь"}</Button>
      {Capacitor.isNativePlatform() && <Button variant="ghost" onClick={() => { setAddress(DEFAULT_SERVER); setMessage(""); }}>Вернуть стандартный адрес</Button>}
      {message && <p role="status" className="text-sm text-ember">{message}</p>}
    </section>
    <p className="text-sm leading-relaxed text-muted-foreground">Голос работает, пока игра открыта. При сворачивании микрофон выключается. После возвращения включите его кнопкой за столом.</p>
    <section className="flex flex-col gap-3 rounded-xl border border-white/10 bg-black/50 p-5">
      <h2 className="font-heading text-xl text-ember">Сообщить о проблеме</h2>
      <p className="text-sm text-muted-foreground">В отчёте — ошибки, версия приложения, сведения об устройстве и размере экрана. Голос не записывается. Выберите чат или почту разработчика в меню отправки.</p>
      <SendLogsButton />
    </section>
    <div className="text-xs text-muted-foreground space-y-1">
      <p>Одесский покер · {Capacitor.isNativePlatform() ? "Android" : "Веб-приложение"} · {APP_VERSION}</p>
      <p>Разработчик — imerkoev</p>
    </div>
    <Button variant="ghost" onClick={() => router.push("/")}><ArrowLeft /> В меню</Button>
  </Backdrop>;
}

class ErrorBoundary extends Component<{ children: ReactNode }, { failed: boolean }> {
  state = { failed: false };
  static getDerivedStateFromError() { return { failed: true }; }
  componentDidCatch(error: Error, info: ErrorInfo) { recordError("web.render-error", new Error(`${error.stack ?? error.message}\n${info.componentStack}`)); }
  render() {
    if (!this.state.failed) return this.props.children;
    return <Backdrop><Title subtitle="Не удалось открыть экран" /><p>Перезапустите приложение. Вход в сетевое лобби сохранён.</p><SendLogsButton /><Button onClick={() => { window.location.hash = "/"; window.location.reload(); }}>Вернуться в меню</Button></Backdrop>;
  }
}
