import type { PlayerId } from "@/lib/game/types";
import { normalizeCode } from "./protocol";
import { persistentSessions, sessionNamespace } from "./client-runtime";

export type Session = { token: string; seat: PlayerId; name: string };

const NAME_KEY = "odessa-poker:name";
const sessionKey = (code: string) =>
  `${sessionNamespace()}:lobby:${normalizeCode(code)}`;
const storage = () => persistentSessions() ? window.localStorage : window.sessionStorage;
const lastLobbyKey = () => `${sessionNamespace()}:last-lobby`;

const listeners = new Set<() => void>();

function notify() {
  for (const listener of listeners) listener();
}

/** Website: sessionStorage per tab. Android: persistent storage, isolated by server. */
export function subscribeSession(listener: () => void): () => void {
  listeners.add(listener);
  window.addEventListener("storage", listener);
  return () => {
    listeners.delete(listener);
    window.removeEventListener("storage", listener);
  };
}

export function readSessionRaw(code: string): string | null {
  return storage().getItem(sessionKey(code));
}

export function parseSession(raw: string | null): Session | null {
  if (!raw) return null;
  try {
    const parsed = JSON.parse(raw) as Partial<Session>;
    if (typeof parsed.token === "string" && typeof parsed.name === "string" &&
        Number.isInteger(parsed.seat) && parsed.seat! >= 0 && parsed.seat! < 4) {
      return parsed as Session;
    }
  } catch {
    // повреждённая запись — считаем, что сессии нет
  }
  return null;
}

export function saveSession(code: string, session: Session): void {
  storage().setItem(sessionKey(code), JSON.stringify(session));
  if (persistentSessions()) storage().setItem(lastLobbyKey(), normalizeCode(code));
  window.localStorage.setItem(NAME_KEY, session.name);
  notify();
}

export function clearSession(code: string): void {
  storage().removeItem(sessionKey(code));
  if (storage().getItem(lastLobbyKey()) === normalizeCode(code)) storage().removeItem(lastLobbyKey());
  notify();
}

export function rememberedName(): string {
  return window.localStorage.getItem(NAME_KEY) ?? "";
}

export function lastLobby(): string | null {
  if (!persistentSessions()) return null;
  const code = storage().getItem(lastLobbyKey());
  return code && parseSession(readSessionRaw(code)) ? code : null;
}
