/** Call directly from a tap: Safari needs the original user gesture for share(). */
export async function shareFile(name: string, text: string, type = "text/plain;charset=utf-8"): Promise<void> {
  const file = new File([text], name, { type });
  if (navigator.share && navigator.canShare?.({ files: [file] })) {
    try { await navigator.share({ files: [file], title: "Одесский покер" }); return; }
    catch (error) { if (error instanceof DOMException && error.name === "AbortError") return; }
  }
  const url = URL.createObjectURL(file);
  const link = document.createElement("a");
  link.href = url; link.download = name;
  document.body.appendChild(link); link.click(); link.remove();
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}
