import { CapacitorHttp } from "@capacitor/core";
import { recordDiagnostic } from "./diagnostics";

/** Native HTTP avoids cross-origin restrictions without relaxing the game server's CORS policy. */
export function nativeRequest(url: string, init: RequestInit = {}): Promise<Response> {
  const path = new URL(url).pathname;
  const label = `${init.method ?? "GET"} ${path}`;
  const signal = init.signal;
  if (signal?.aborted) return Promise.reject(new DOMException("Aborted", "AbortError"));
  return new Promise((resolve, reject) => {
    let settled = false;
    const finish = (action: () => void) => {
      if (settled) return;
      settled = true;
      signal?.removeEventListener("abort", abort);
      action();
    };
    const abort = () => finish(() => reject(new DOMException("Aborted", "AbortError")));
    signal?.addEventListener("abort", abort, { once: true });
    if (init.method === "POST" && !path.endsWith("/voice")) recordDiagnostic("http.action", label);
    void CapacitorHttp.request({
      url,
      method: init.method ?? "GET",
      headers: Object.fromEntries(new Headers(init.headers).entries()),
      data: init.body ?? undefined,
      responseType: "text",
      connectTimeout: 10000,
      readTimeout: 35000,
      disableRedirects: true,
    }).then((result) => {
      if (result.status >= 400) recordDiagnostic("http.failure", `${label} status=${result.status}`);
      finish(() => {
        try {
          const body = result.status === 204 || result.status === 304 ? null :
            typeof result.data === "string" ? result.data : JSON.stringify(result.data);
          resolve(new Response(body, { status: result.status, headers: result.headers }));
        } catch (error) { reject(error); }
      });
    }, (error: unknown) => finish(() => {
      recordDiagnostic("http.network-error", label);
      reject(error);
    }));
  });
}
