import { Capacitor, registerPlugin } from "@capacitor/core";
import { Share } from "@capacitor/share";
import { APP_VERSION, DEVELOPER } from "./app-info";
import { shareFile } from "./share-file";

const Diagnostics = registerPlugin<{
  record(event: { kind: string; message: string; critical: boolean }): Promise<void>;
  heartbeat(): Promise<void>;
  status(): Promise<{ pending: boolean }>;
  dismiss(): Promise<void>;
  export(): Promise<{ uri: string }>;
}>("Diagnostics");
const WEB_LOG = "odessa-poker:web-diagnostics";
const WEB_PENDING = "odessa-poker:web-error";
const WEB_CRITICAL = "odessa-poker:web-last-error";
const SESSION_MARKER = "odessa-poker:web-session";
let memoryLog: string | null = null;
let memoryCritical: string | null = null;
let memoryPending = false;
const read = (key: string) => { try { return localStorage.getItem(key); } catch { return null; } };

export function redactDiagnostic(value: string): string {
  return value
    .replace(/(https?:\/\/[^\s?"'<>]+)\?[^\s"'<>]*/g, "$1?[redacted]")
    .replace(/bearer\s+[^\s"'<>]+/gi, "Bearer [redacted]")
    .replace(/(["']?(?:token|password|secret|authorization|cookie)["']?\s*[:=]\s*)[^\s,}]+/gi, "$1[redacted]")
    .replace(/(\/api\/lobbies\/|\/lobby\/)[a-z]{4}/gi, "$1[code]")
    .slice(0, 24000);
}

export function recordDiagnostic(kind: string, message = "", critical = false): void {
  const clean = redactDiagnostic(message);
  if (Capacitor.isNativePlatform()) {
    void Diagnostics.record({ kind, message: clean, critical }).then(() => {
      if (critical) window.dispatchEvent(new Event("odessa:diagnostic-error"));
    }).catch(() => {});
  } else {
    const line = `${new Date().toISOString()} ${kind} ${clean}`;
    memoryLog = `${memoryLog ?? read(WEB_LOG) ?? ""}\n${line}`.slice(-128000);
    if (critical) { memoryPending = true; memoryCritical = line; }
    try {
      if (critical) { localStorage.setItem(WEB_PENDING, "1"); localStorage.setItem(WEB_CRITICAL, line); }
      localStorage.setItem(WEB_LOG, memoryLog);
    } catch { /* A full/disabled store still leaves an in-memory report. */ }
    if (critical) window.dispatchEvent(new Event("odessa:diagnostic-error"));
  }
}

export function recordError(kind: string, error: unknown): void {
  const message = error instanceof Error ? `${error.name}: ${error.message}\n${error.stack ?? ""}` : String(error);
  recordDiagnostic(kind, message, true);
}

export async function hasPendingReport(): Promise<boolean> {
  if (Capacitor.isNativePlatform()) return (await Diagnostics.status()).pending;
  return memoryPending || read(WEB_PENDING) === "1";
}

export async function dismissReport(): Promise<void> {
  if (Capacitor.isNativePlatform()) await Diagnostics.dismiss();
  else { memoryPending = false; try { localStorage.removeItem(WEB_PENDING); } catch { /* storage disabled */ } }
}

export async function shareDiagnostics(): Promise<void> {
  recordDiagnostic("report.export");
  if (Capacitor.isNativePlatform()) {
    const { uri } = await Diagnostics.export();
    await Share.share({ title: "Логи Одесского покера", files: [uri], dialogTitle: "Отправить логи разработчику" });
  } else {
    const report = [
      `Одесский покер ${APP_VERSION} · Разработчик: ${DEVELOPER}`,
      `Время: ${new Date().toISOString()}`,
      `Браузер: ${navigator.userAgent}`,
      `Экран: ${innerWidth}x${innerHeight}, dpr=${devicePixelRatio}`,
      `Последний сбой: ${memoryCritical ?? read(WEB_CRITICAL) ?? "нет"}`,
      memoryLog ?? read(WEB_LOG) ?? "Нет событий",
    ].join("\n");
    await shareFile("odesskiy-poker-logs.txt", report);
  }
}

export function installDiagnostics(): void {
  window.addEventListener("error", (event) => {
    recordError("web.error", event.error ?? `${event.message} ${event.filename}:${event.lineno}:${event.colno}`);
  });
  window.addEventListener("unhandledrejection", (event) => recordError("web.promise", event.reason));
  const viewport = () => recordDiagnostic("web.viewport", `${innerWidth}x${innerHeight} dpr=${devicePixelRatio}`);
  let resizeTimer: ReturnType<typeof setTimeout>;
  window.addEventListener("resize", () => { clearTimeout(resizeTimer); resizeTimer = setTimeout(viewport, 400); });
  const route = () => recordDiagnostic("web.route", location.hash);
  window.addEventListener("hashchange", route);
  window.addEventListener("online", () => recordDiagnostic("network.online"));
  window.addEventListener("offline", () => recordDiagnostic("network.offline"));
  window.addEventListener("odessa:app-resume", () => { recordDiagnostic("web.resume"); viewport(); });
  window.addEventListener("odessa:app-background", () => recordDiagnostic("web.background"));
  recordDiagnostic("web.start", `version=${APP_VERSION} developer=${DEVELOPER}`); viewport(); route();
  if (Capacitor.isNativePlatform()) {
    const beat = () => { if (!document.hidden) void Diagnostics.heartbeat().catch(() => {}); };
    beat(); setInterval(beat, 2000);
  } else {
    // Session-local marker avoids mistaking a second browser tab for a crash.
    try {
      if (sessionStorage.getItem(SESSION_MARKER) === "active") {
        recordDiagnostic("web.interrupted-session", "Предыдущий сеанс прервался без события закрытия; причина неизвестна", true);
      }
    } catch { /* storage disabled */ }
    const mark = (active: boolean) => { try { sessionStorage.setItem(SESSION_MARKER, active ? "active" : "closed"); } catch { /* storage disabled */ } };
    let previous = performance.now();
    let visible = !document.hidden;
    const reset = (active: boolean) => { visible = active; previous = performance.now(); mark(active); };
    document.addEventListener("visibilitychange", () => reset(!document.hidden));
    window.addEventListener("pagehide", () => reset(false));
    window.addEventListener("pageshow", () => reset(!document.hidden));
    mark(visible);
    setInterval(() => {
      const now = performance.now();
      if (visible && !document.hidden && now - previous > 10000) {
        recordDiagnostic("web.long-pause", `Пауза интерфейса ${Math.round(now - previous)} мс; возможное зависание или приостановка браузера`, true);
      }
      previous = now;
    }, 2000);
  }
}
