/** Platform services are injected by the Android entry point. The website keeps its defaults. */
export type ClientRuntime = {
  apiOrigin: string;
  preferPolling: boolean;
  persistentSessions: boolean;
  request?: (url: string, init: RequestInit) => Promise<Response>;
  lobbyUrl?: (code: string) => string;
  copyText?: (text: string) => Promise<void>;
  saveTextFile?: (name: string, text: string) => Promise<void>;
};

let runtime: ClientRuntime | null = null;

export function normalizeServerOrigin(value: string): string {
  let url: URL;
  try {
    url = new URL(value.trim());
  } catch {
    throw new Error("Введите адрес сайта игры, начиная с https://");
  }
  if (url.protocol !== "https:" || url.username || url.password ||
      url.pathname !== "/" || url.search || url.hash) {
    throw new Error("Нужен HTTPS-адрес сайта без логина, пути и параметров");
  }
  return url.origin;
}

export function configureClientRuntime(value: ClientRuntime | null): void {
  runtime = value ? { ...value, apiOrigin: normalizeServerOrigin(value.apiOrigin) } : null;
}

export function prefersPolling(): boolean {
  return runtime?.preferPolling ?? false;
}

export function persistentSessions(): boolean {
  return runtime?.persistentSessions ?? false;
}

export function sessionNamespace(): string {
  return runtime ? `odessa-poker:mobile:${runtime.apiOrigin}` : "odessa-poker";
}

export function publicLobbyUrl(code: string): string {
  if (runtime?.lobbyUrl) return runtime.lobbyUrl(code);
  return `${runtime?.apiOrigin ?? window.location.origin}/lobby/${encodeURIComponent(code)}`;
}

export function apiFetch(path: string, init: RequestInit = {}): Promise<Response> {
  if (!path.startsWith("/api/")) throw new Error("Invalid API path");
  const url = runtime ? `${runtime.apiOrigin}${path}` : path;
  return runtime?.request ? runtime.request(url, init) : fetch(url, init);
}

export async function copyText(text: string): Promise<void> {
  if (runtime?.copyText) return runtime.copyText(text);
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return;
    }
  } catch { /* Older browsers can still use the selection fallback. */ }
  const area = document.createElement("textarea");
  area.value = text;
  area.setAttribute("readonly", "");
  area.style.position = "fixed";
  area.style.left = "-9999px";
  document.body.appendChild(area);
  area.select();
  const copied = document.execCommand("copy");
  area.remove();
  if (!copied) throw new Error("Не удалось скопировать");
}

export async function saveTextFile(name: string, text: string): Promise<void> {
  if (runtime?.saveTextFile) return runtime.saveTextFile(name, text);
  const blob = new Blob([text], { type: "text/html;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = name;
  link.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

export function clientNotice(message: string): void {
  window.dispatchEvent(new CustomEvent("odessa:notice", { detail: message }));
}
